import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var h2 = React.useState([]);
    return <div className="dschartlegend-example">
    <style>{exampleStyles}</style>
    <S.DsChartLegend series={[{ name: 'Скорость', unit: 'км/ч' }, { name: 'Топливо', unit: 'л' }, { name: 'Температура', unit: '°C' }]} hidden={h2[0]} onToggle={function (n) { h2[1](h2[0].indexOf(n) > -1 ? h2[0].filter(function (x) { return x !== n; }) : h2[0].concat(n)); }}/>
    </div>;
}

const exampleStyles = ".dschartlegend-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dschartlegend-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dschartlegend-example p{margin:0}\n";

export { App as Example };
